// Environment readiness check for the workbench.
//
// Answers one question: everything the 19 bundled templates need is actually on
// this machine — node packages, model files, working ComfyUI, built server?
//
// Reads docs/DEPENDENCIES.json (generated by audit-template-deps.mjs) as the source
// of truth rather than keeping its own list, so adding a template cannot silently
// fall out of the check.
//
// Usage:
//   node scripts/check-environment.mjs           # 人读
//   node scripts/check-environment.mjs --json    # 机器读（控制台 / API 用）
//   node scripts/check-environment.mjs --quiet   # 只输出结论行
import { existsSync, readFileSync, readdirSync, statSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';

// 工作台根目录。三种来源，按优先级：
//   1. --root <path>（控制台传入计划任务实际指向的目录）
//   2. BEATDESIGN_WORKBENCH_HOME 环境变量
//   3. 本脚本所在位置的上两级（直接在仓库里跑时）
// 为什么需要 1 和 2：控制台安装包只有 25 MB，不含工作台源码；
// 用户机器上的完整工作台可能在别处，自检查的必须是真正在跑的那个。
const ROOT = (() => {
  const rootArg = (() => {
    const i = process.argv.indexOf('--root');
    return i >= 0 ? process.argv[i + 1] : undefined;
  })();
  if (rootArg) return resolve(rootArg.trim());
  const envHome = process.env.BEATDESIGN_WORKBENCH_HOME;
  if (envHome) return resolve(envHome.trim());
  return resolve(process.argv[1], '../..');
})();
const JSON_MODE = process.argv.includes('--json');
const QUIET = process.argv.includes('--quiet');

const checks = [];
const add = (id, label, status, detail, hint, sources) => {
  checks.push({ id, label, status, detail, hint, sources: sources ?? undefined });
};

/**
 * 安装渠道。
 *
 * 自检只回答「缺什么」，这个文件回答「去哪儿拿」。分开是因为下载地址会变，
 * 而检查逻辑不该跟着改。缺东西时把渠道附在条目上，换机器部署照着补就行。
 */
const loadInstallSources = () => {
  const path = join(ROOT, 'data', 'install-sources.json');
  try {
    return JSON.parse(readFileSync(path, 'utf8'));
  } catch {
    return { models: {}, nodes: {}, runtime: {}, bundles: [] };
  }
};
const installSources = loadInstallSources();

/** 查节点的下载渠道。 */
const nodeSource = (name) => installSources.nodes?.[name] ?? null;

/** 查模型文件的下载渠道，文件名可能带子目录。 */
const modelSource = (basename) => {
  const models = installSources.models ?? {};
  if (models[basename]) return models[basename];
  const lower = String(basename).toLowerCase();
  for (const [key, value] of Object.entries(models)) {
    if (key.toLowerCase() === lower) return value;
  }
  return null;
};

/** 把一批来源整理成 UI 能直接渲染的结构。 */
const collectSources = (entries) => {
  const out = [];
  const seen = new Set();
  for (const { name, source } of entries) {
    if (!source) continue;
    const key = `${source.kind}|${source.url}`;
    if (seen.has(key)) {
      // 同一个地址覆盖多个文件时合并名字，避免重复列五行
      const existing = out.find((item) => `${item.kind}|${item.url}` === key);
      if (existing) existing.covers.push(name);
      continue;
    }
    seen.add(key);
    out.push({
      kind: source.kind,
      url: source.url,
      note: source.note ?? '',
      dir: source.dir,
      covers: [name],
    });
  }
  return out;
};

// ── 配置
const configPath = join(ROOT, 'data', 'comfyui.config.json');
let config = {};
try {
  config = JSON.parse(readFileSync(configPath, 'utf8'));
} catch {
  // 缺失下面会单独报
}

const baseUrl = String(config.baseUrl ?? 'http://127.0.0.1:8188').replace(/\/+$/, '');
const isLocalComfy =
  /\/\/(127\.0\.0\.1|localhost|\[::1\])(:|\/|$)/.test(baseUrl) || baseUrl === '';

// ComfyUI 安装根目录的确定顺序：
//   1. BEATDESIGN_COMFYUI_HOME 环境变量（临时覆盖）
//   2. data/comfyui.config.json 的 pythonPath 反推（控制台「ComfyUI 位置」写这里）
//   3. 常见盘符猜一个
// 关键：用户的配置说在哪就在哪。找不到就如实报「你说的位置没东西」，
// 不要偷偷退回某个默认路径 —— 那样检查的是别的目录，结果全是误导。
const comfyRootSource = (() => {
  // Trim every path that comes from outside.
  // `set VAR=E:\ComfyUI && node ...` in cmd.exe folds the space before `&&`
  // into the value, so the variable arrives as "E:\ComfyUI " and existsSync
  // reports the directory as missing even though it is right there. The same
  // trailing-space hazard shows up when a user pastes a path with a trailing
  // space into the console's folder picker.
  const envRoot = String(process.env.BEATDESIGN_COMFYUI_HOME ?? '').trim();
  if (envRoot) return { root: envRoot, source: 'BEATDESIGN_COMFYUI_HOME' };
  const py = String(config.pythonPath ?? '').trim();
  if (py) {
    const idx = py.toLowerCase().indexOf('python_embeded');
    if (idx > 0) {
      return { root: py.slice(0, idx).replace(/[\\/]+$/, ''), source: 'data/comfyui.config.json' };
    }
    // pythonPath 有值但不像 <root>\python_embeded\python.exe，直接用它的两层上级
    const guess = dirname(dirname(py));
    if (guess) return { root: guess, source: 'data/comfyui.config.json（推断）' };
  }
  for (const candidate of ['E:\\ComfyUI', 'D:\\ComfyUI', 'C:\\ComfyUI']) {
    try {
      if (existsSync(join(candidate, 'python_embeded', 'python.exe'))) {
        return { root: candidate, source: '自动探测' };
      }
    } catch {
      /* 无权限就跳过 */
    }
  }
  return { root: null, source: '未配置' };
})();

const comfyRoot = comfyRootSource.root;
const comfyDir = comfyRoot ? join(comfyRoot, 'ComfyUI') : null;

// ── 1. 构建产物
const serverEntry = join(ROOT, '.output', 'server', 'index.mjs');if (existsSync(serverEntry)) {
  add('build', '构建产物', 'pass', '.output/server/index.mjs 存在');
} else {
  add('build', '构建产物', 'fail', '缺少 .output/server/index.mjs', '跑 pnpm build');
}

// ── 2. 依赖
const deps = join(ROOT, 'node_modules');
if (existsSync(deps)) {
  add('deps', 'Node 依赖', 'pass', 'node_modules 存在');
} else {
  add('deps', 'Node 依赖', 'fail', '缺少 node_modules', '跑 pnpm install');
}

// ── 3. 配置
if (existsSync(configPath)) {
  add('config', 'ComfyUI 配置', 'pass', 'data/comfyui.config.json 存在');
} else {
  add('config', 'ComfyUI 配置', 'warn', '缺少 data/comfyui.config.json', '首次启动会自动生成');
}

// ── 3.5 自检到底在检查哪个 ComfyUI
// 用户可能在控制台里选了别的盘，这时候所有文件类检查都该看那个位置。
// 位置不存在就明确说清楚，而不是默默退回默认路径给出一堆无关的结论。
if (!comfyRoot) {
  add(
    'comfy-location',
    'ComfyUI 位置',
    'fail',
    '还没指定 ComfyUI 在哪',
    '点控制台「ComfyUI 位置」选一个目录，或解压部署包后指向 manke\\ComfyUI'
  );
} else if (!existsSync(comfyRoot)) {
  add(
    'comfy-location',
    'ComfyUI 位置',
    'fail',
    `指定的目录不存在：${comfyRoot}`,
    `来源：${comfyRootSource.source}。重新点「ComfyUI 位置」选一个存在的目录`
  );
} else if (!existsSync(join(comfyRoot, 'python_embeded', 'python.exe'))) {
  add(
    'comfy-location',
    'ComfyUI 位置',
    'fail',
    `${comfyRoot} 下没有 python_embeded\\python.exe`,
    '这不是一个完整的 ComfyUI 目录，或者部署包还没解压'
  );
} else if (!existsSync(join(comfyRoot, 'ComfyUI'))) {
  add(
    'comfy-location',
    'ComfyUI 位置',
    'fail',
    `${comfyRoot} 下没有 ComfyUI 子目录`,
    '标准的 ComfyUI 结构是 <根>\\python_embeded + <根>\\ComfyUI'
  );
} else {
  add('comfy-location', 'ComfyUI 位置', 'pass', `${comfyRoot}（来源：${comfyRootSource.source}）`);
}

if (isLocalComfy && config.pythonPath) {
  if (existsSync(String(config.pythonPath))) {
    add('pythonPath', 'ComfyUI 解释器', 'pass', String(config.pythonPath));
  } else {
    add(
      'pythonPath',
      'ComfyUI 解释器',
      'fail',
      `路径不存在：${config.pythonPath}`,
      '改 data/comfyui.config.json 的 pythonPath'
    );
  }
}

// ── 4. ComfyUI 是否在跑
try {
  const res = await fetch(`${baseUrl}/system_stats`, { signal: AbortSignal.timeout(4000) });
  if (res.ok) {
    const stats = await res.json();
    const dev = stats?.devices?.[0];
    const vram = dev ? ` · ${Math.round(dev.vram_total / 1024 ** 3)} GB 显存` : '';
    add('comfyui', 'ComfyUI 服务', 'pass', `${baseUrl} 可访问${vram}`);
  } else {
    add('comfyui', 'ComfyUI 服务', 'fail', `HTTP ${res.status}`, '在服务控制台启动 ComfyUI');
  }
} catch {
  add('comfyui', 'ComfyUI 服务', 'fail', `${baseUrl} 无响应`, '在服务控制台启动 ComfyUI');
}

// ── 5. 模板
const wfDir = join(ROOT, 'data', 'comfyui', 'workflows');
const templates = existsSync(wfDir)
  ? readdirSync(wfDir).filter((f) => f.toLowerCase().endsWith('.json'))
  : [];
add(
  'templates',
  '工作流模板',
  templates.length > 0 ? 'pass' : 'fail',
  `${templates.length} 个`,
  templates.length === 0 ? '检查 data/comfyui/workflows 目录' : undefined
);

// ── 6. 依赖清单
const manifestPath = join(ROOT, 'docs', 'DEPENDENCIES.json');
let manifest = null;
try {
  manifest = JSON.parse(readFileSync(manifestPath, 'utf8'));
} catch {
  add(
    'manifest',
    '依赖清单',
    'warn',
    '没有 docs/DEPENDENCIES.json',
    '跑 node scripts/audit-template-deps.mjs 生成'
  );
}

if (manifest) {
  // 清单可能比磁盘上的模板旧
  if (manifest.templateCount !== templates.length) {
    add(
      'manifest-fresh',
      '依赖清单时效',
      'warn',
      `清单记 ${manifest.templateCount} 个模板，磁盘有 ${templates.length} 个`,
      '重新生成：node scripts/audit-template-deps.mjs'
    );
  } else {
    add('manifest-fresh', '依赖清单时效', 'pass', `与磁盘一致（${templates.length} 个模板）`);
  }

  // ── 7. 节点包
  if (!isLocalComfy) {
    add('nodes', '自定义节点包', 'warn', 'ComfyUI 不在本机，无法检查文件', undefined);
  } else if (!comfyDir) {
    add('nodes', '自定义节点包', 'fail', '还没指定 ComfyUI 位置', '点控制台「ComfyUI 位置」选一个目录');
  } else {
    const cnDir = join(comfyDir, 'custom_nodes');
    const missingPkgs = (manifest.nodePackages ?? []).filter(
      (p) => !existsSync(join(cnDir, p.name))
    );
    if (missingPkgs.length === 0) {
      add('nodes', '自定义节点包', 'pass', `${manifest.nodePackages.length} / ${manifest.nodePackages.length} 到位`);
    } else {
      const names = missingPkgs.map((p) => p.name);
      const sources = collectSources(
        missingPkgs.map((p) => ({ name: p.name, source: nodeSource(p.name) }))
      );
      add(
        'nodes',
        '自定义节点包',
        'fail',
        `缺 ${missingPkgs.length} 个：${names.slice(0, 4).join('、')}${names.length > 4 ? ' …' : ''}`,
        `ComfyUI/custom_nodes 下补齐：${names.join('、')}`,
        sources.length ? sources : undefined
      );
    }

    // 节点包里的 Python 依赖（粗略：看有没有 requirements.txt 与 __init__.py）
    const broken = (manifest.nodePackages ?? []).filter((p) => {
      const dir = join(cnDir, p.name);
      if (!existsSync(dir)) return false;
      try {
        const entries = readdirSync(dir);
        return !entries.includes('__init__.py') && !entries.includes('nodes.py');
      } catch {
        return true;
      }
    });
    if (broken.length) {
      add(
        'nodes-importable',
        '节点包可加载',
        'warn',
        `${broken.length} 个包目录里没有 __init__.py / nodes.py：${broken.map((p) => p.name).join('、')}`,
        '可能是空目录或复制中断'
      );
    } else if (missingPkgs.length === 0) {
      add('nodes-importable', '节点包可加载', 'pass', '每个包都有入口文件');
    }

    // ── 8. 模型文件
    const index = new Map();
    const dirNames = new Set();
    for (const root of [join(comfyDir, 'models'), join(comfyDir, 'input')]) {      if (!existsSync(root)) continue;
      const walk = (d) => {
        let entries;
        try {
          entries = readdirSync(d, { withFileTypes: true });
        } catch {
          return;
        }
        for (const e of entries) {
          const p = join(d, e.name);
          if (e.isDirectory()) {
            dirNames.add(e.name);
            walk(p);
          } else if (!index.has(e.name)) {
            index.set(e.name, p);
          }
        }
      };
      walk(root);
    }

    const missingFiles = [];
    let presentFiles = 0;
    let presentBytes = 0;
    for (const f of manifest.files ?? []) {
      const hit = index.get(f.basename);
      if (hit) {
        presentFiles += 1;
        try {
          presentBytes += statSync(hit).size;
        } catch {
          /* 大小读不到不影响存在性判断 */
        }
      } else if (dirNames.has(f.basename)) {
        // 目录型资源（TTS 权重目录）
        presentFiles += 1;
      } else {
        missingFiles.push(f);
      }
    }

    const total = (manifest.files ?? []).length;
    if (missingFiles.length === 0) {
      add('models', '模型文件', 'pass', `${presentFiles} / ${total} 就位 · ${(presentBytes / 1024 ** 3).toFixed(1)} GB`);
    } else {
      const names = missingFiles.map((f) => f.basename);
      const sources = collectSources(
        missingFiles.map((f) => ({ name: f.basename, source: modelSource(f.basename) }))
      );
      // 整包网盘链接排在最前：缺一堆文件时，一条链接比逐个去搜有用得多
      const bundles = (installSources.bundles ?? [])
        .filter((b) => b.primary && b.url)
        .map((b) => ({
          kind: b.kind,
          url: b.url,
          note: b.note ?? '',
          code: b.code,
          covers: [b.covers ?? b.name],
        }));
      add(
        'models',
        '模型文件',
        'fail',
        `${presentFiles} / ${total} 就位，缺 ${missingFiles.length} 个 · ${(presentBytes / 1024 ** 3).toFixed(1)} GB`,
        `缺：${names.slice(0, 3).join('、')}${names.length > 3 ? ` …（共 ${names.length} 个）` : ''}`,
        [...bundles, ...sources]
      );
    }

    // 缺的模型卡住哪些模板
    if (missingFiles.length) {
      const blocked = new Set();
      for (const f of missingFiles) for (const t of f.templates ?? []) blocked.add(t);
      add(
        'models-impact',
        '受影响模板',
        blocked.size ? 'warn' : 'pass',
        blocked.size ? `${blocked.size} 个模板缺模型：${[...blocked].slice(0, 3).join('、')}${blocked.size > 3 ? ' …' : ''}` : '无'
      );
    }
  }
}

// ── 安装渠道
// 这一项永远通过：它的用途不是判断，而是换机器时告诉你去哪儿下。
// 缺什么的时候，失败项里会附带具体渠道；这里给的是整体入口和整包渠道。
{
  const nodeCount = Object.keys(installSources.nodes ?? {}).length;
  const modelCount = Object.keys(installSources.models ?? {}).length;
  const bundles = installSources.bundles ?? [];
  add(
    'install-sources',
    '安装渠道',
    'pass',
    `${nodeCount} 个节点包 · ${modelCount} 个模型 · ${bundles.length} 个整包渠道`,
    '缺文件时点开对应条目的来源链接，或见 docs/DEPENDENCIES.md',
    [
      ...bundles.map((b) => ({
        kind: b.kind,
        url: b.url,
        note: b.note,
        covers: [b.name],
      })),
      ...Object.entries(installSources.runtime ?? {}).map(([, value]) => ({
        kind: value.kind,
        url: value.url,
        note: value.label ?? '',
        covers: [value.note ?? ''],
      })),
    ].filter((item) => item.url)
  );
}

// ── 汇总
const summary = {
  pass: checks.filter((c) => c.status === 'pass').length,
  warn: checks.filter((c) => c.status === 'warn').length,
  fail: checks.filter((c) => c.status === 'fail').length,
};
const ok = summary.fail === 0;

if (JSON_MODE) {
  console.log(
    JSON.stringify(
      { ok, summary, comfyRoot, baseUrl, templates: templates.length, checks },
      null,
      2
    )
  );
} else if (!QUIET) {
  const icon = { pass: '✓', warn: '!', fail: '×' };
  const color = { pass: '\x1b[32m', warn: '\x1b[33m', fail: '\x1b[31m' };
  console.log('');
  console.log('漫客工作台 · 环境自检');
  console.log('='.repeat(56));
  for (const c of checks) {
    console.log(
      `${color[c.status]}${icon[c.status]}\x1b[0m ${c.label.padEnd(14, ' ')} ${c.detail}`
    );
    if (c.hint && c.status !== 'pass') console.log(`  ${' '.repeat(17)}→ ${c.hint}`);
    // 缺东西时把下载地址打出来，省得再翻文档
    if (c.sources?.length && c.status !== 'pass') {
      for (const s of c.sources.slice(0, 6)) {
        console.log(`  ${' '.repeat(17)}  [${s.kind}] ${s.url}`);
        if (s.code) console.log(`  ${' '.repeat(17)}    提取码 ${s.code}`);
      }
    }
  }
  console.log('='.repeat(56));
  console.log(
    `通过 ${summary.pass}  警告 ${summary.warn}  失败 ${summary.fail}   →  ${ok ? '可以开工' : '先处理失败项'}`
  );
  console.log('');
} else {
  console.log(`${ok ? 'OK' : 'FAIL'} pass=${summary.pass} warn=${summary.warn} fail=${summary.fail}`);
}

process.exit(ok ? 0 : 1);
